   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Camino de cuatro pasos de un problema estequiométrico\">\n        <defs><marker id=\"es2\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--muted)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-weight=\"700\" text-anchor=\"middle\" font-size=\"13\">\n          <rect x=\"20\" y=\"20\" width=\"100\" height=\"28\" rx=\"14\" fill=\"var(--sun)\"/><text x=\"70\" y=\"39\" fill=\"#fff\">8 g H₂</text><rect x=\"140\" y=\"58\" width=\"100\" height=\"28\" rx=\"14\" fill=\"var(--pen)\"/><text x=\"190\" y=\"77\" fill=\"#fff\">4 mol H₂</text><rect x=\"20\" y=\"96\" width=\"100\" height=\"28\" rx=\"14\" fill=\"var(--pen)\"/><text x=\"70\" y=\"115\" fill=\"#fff\">4 mol H₂O</text><rect x=\"140\" y=\"134\" width=\"100\" height=\"28\" rx=\"14\" fill=\"var(--leaf)\"/><text x=\"190\" y=\"153\" fill=\"#fff\">72 g H₂O</text>\n          <path d=\"M120 40 L 140 56\" stroke=\"var(--muted)\" stroke-width=\"2\" marker-end=\"url(#es2)\"/><path d=\"M140 82 L 120 96\" stroke=\"var(--muted)\" stroke-width=\"2\" marker-end=\"url(#es2)\"/><path d=\"M120 116 L 140 132\" stroke=\"var(--muted)\" stroke-width=\"2\" marker-end=\"url(#es2)\"/>\n          <g font-size=\"11\" fill=\"var(--muted)\"><text x=\"214\" y=\"40\">÷ 2 g/mol</text><text x=\"56\" y=\"80\">× 2/2</text><text x=\"214\" y=\"116\">× 18 g/mol</text></g>\n        </g>\n      </svg>"
