   "titulo": "Las cuatro fórmulas que lo resuelven casi todo",
   "svg": "<svg viewBox=\"0 0 640 220\" role=\"img\" aria-label=\"Fórmulas: moles a partir de masa, partículas, molaridad y volumen de gas\">\n      <rect width=\"640\" height=\"220\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"16\" y=\"30\" width=\"146\" height=\"160\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--sun)\" stroke-width=\"3\"/>\n          <text x=\"89\" y=\"104\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--sun)\" font-family=\"Baloo 2, sans-serif\">n = m / M</text>\n          <text x=\"89\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">masa → moles</text><rect x=\"170\" y=\"30\" width=\"146\" height=\"160\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"243\" y=\"104\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">N = n · Nₐ</text>\n          <text x=\"243\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">moles → partículas</text><rect x=\"324\" y=\"30\" width=\"146\" height=\"160\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"397\" y=\"104\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">M = n / V</text>\n          <text x=\"397\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">molaridad (mol/L)</text><rect x=\"478\" y=\"30\" width=\"146\" height=\"160\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"551\" y=\"104\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">V = n · 22,4 L</text>\n          <text x=\"551\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">gas a 0 °C y 1 atm</text>\n    </svg>"
