   "svg": "<svg viewBox=\"0 0 640 220\" role=\"img\" aria-label=\"Conducción, convección y radiación con dónde ocurren y un ejemplo\">\n      <rect width=\"640\" height=\"220\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"20\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"3\"/>\n          <text x=\"115\" y=\"58\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Baloo 2, sans-serif\">Conducción</text>\n          <text x=\"115\" y=\"100\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">por contacto, en sólidos</text>\n          <text x=\"115\" y=\"122\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">partícula a partícula</text>\n          <text x=\"115\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">la cuchara en la sopa</text><rect x=\"226\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"321\" y=\"58\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">Convección</text>\n          <text x=\"321\" y=\"100\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">en líquidos y gases</text>\n          <text x=\"321\" y=\"122\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">corrientes que suben y bajan</text>\n          <text x=\"321\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">el radiador calienta la sala</text><rect x=\"432\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--sun)\" stroke-width=\"3\"/>\n          <text x=\"527\" y=\"58\" text-anchor=\"middle\" font-size=\"21\" font-weight=\"700\" fill=\"var(--sun)\" font-family=\"Baloo 2, sans-serif\">Radiación</text>\n          <text x=\"527\" y=\"100\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">ondas, también en el vacío</text>\n          <text x=\"527\" y=\"122\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">no necesita materia</text>\n          <text x=\"527\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">el calor del Sol</text>\n    </svg>"
