   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Trayectoria curva de A a B y desplazamiento en línea recta\">\n        <defs><marker id=\"mv1\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--red)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M40 130 C 60 30, 140 20, 150 90 S 210 150, 220 60\" fill=\"none\" stroke=\"var(--pen)\" stroke-width=\"3\" stroke-dasharray=\"7 5\"/>\n        <path d=\"M40 130 L 214 66\" stroke=\"var(--red)\" stroke-width=\"3.5\" marker-end=\"url(#mv1)\"/>\n        <circle cx=\"40\" cy=\"130\" r=\"6\" fill=\"var(--ink)\"/><circle cx=\"220\" cy=\"60\" r=\"6\" fill=\"var(--ink)\"/>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-size=\"13\" font-weight=\"700\"><text x=\"26\" y=\"152\" fill=\"var(--ink)\">A</text><text x=\"228\" y=\"56\" fill=\"var(--ink)\">B</text><text x=\"70\" y=\"40\" fill=\"var(--pen)\">trayectoria</text><text x=\"120\" y=\"122\" fill=\"var(--red)\">desplazamiento</text></g>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Coche que pasa de 0 a 20 metros por segundo en 5 segundos: aceleración de 4 metros por segundo al cuadrado\">\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M14 120 H 246\" stroke=\"var(--muted)\" stroke-width=\"2\"/>\n        <rect x=\"30\" y=\"92\" width=\"56\" height=\"20\" rx=\"6\" fill=\"var(--red)\"/><rect x=\"40\" y=\"80\" width=\"30\" height=\"14\" rx=\"4\" fill=\"var(--red)\"/><circle cx=\"42\" cy=\"114\" r=\"7\" fill=\"var(--ink)\"/><circle cx=\"74\" cy=\"114\" r=\"7\" fill=\"var(--ink)\"/>\n          <text x=\"58\" y=\"68\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">0 m/s</text><text x=\"58\" y=\"146\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t = 0 s</text><rect x=\"170\" y=\"92\" width=\"56\" height=\"20\" rx=\"6\" fill=\"var(--red)\"/><rect x=\"180\" y=\"80\" width=\"30\" height=\"14\" rx=\"4\" fill=\"var(--red)\"/><circle cx=\"182\" cy=\"114\" r=\"7\" fill=\"var(--ink)\"/><circle cx=\"214\" cy=\"114\" r=\"7\" fill=\"var(--ink)\"/>\n          <text x=\"198\" y=\"68\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">20 m/s</text><text x=\"198\" y=\"146\" text-anchor=\"middle\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t = 5 s</text>\n        <text x=\"130\" y=\"30\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">a = (20 − 0) / 5 = 4 m/s²</text>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Gráficas del MRU: posición recta inclinada y velocidad horizontal\">\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M34 30 V 140 H 124\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"/>\n  <text x=\"124\" y=\"156\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text><text x=\"28\" y=\"34\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">x</text><path d=\"M34 130 L 118 44\" stroke=\"var(--pen)\" stroke-width=\"3.5\"/>\n        <path d=\"M160 30 V 140 H 250\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"156\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text><text x=\"154\" y=\"34\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">v</text><path d=\"M160 80 H 246\" stroke=\"var(--leaf)\" stroke-width=\"3.5\"/>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\"><text x=\"80\" y=\"170\" fill=\"var(--pen)\">x-t: recta</text><text x=\"205\" y=\"170\" fill=\"var(--leaf)\">v-t: horizontal</text></g>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Gráficas del MRUA: posición en parábola y velocidad recta inclinada\">\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M34 30 V 140 H 124\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"/>\n  <text x=\"124\" y=\"156\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text><text x=\"28\" y=\"34\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">x</text><path d=\"M34 138 Q 90 136 118 40\" fill=\"none\" stroke=\"var(--pen)\" stroke-width=\"3.5\"/>\n        <path d=\"M160 30 V 140 H 250\" fill=\"none\" stroke=\"var(--muted)\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"156\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text><text x=\"154\" y=\"34\" text-anchor=\"end\" font-size=\"12\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">v</text><path d=\"M160 140 L 246 52 V 140 Z\" fill=\"var(--leaf)\" opacity=\".2\"/><path d=\"M160 140 L 246 52\" stroke=\"var(--leaf)\" stroke-width=\"3.5\"/>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\"><text x=\"80\" y=\"170\" fill=\"var(--pen)\">x-t: parábola</text><text x=\"205\" y=\"170\" fill=\"var(--leaf)\">área = distancia</text></g>\n      </svg>",
