   "svg": "<svg viewBox=\"0 0 640 230\" role=\"img\" aria-label=\"Comparación de MRU y MRUA: aceleración, ecuaciones y forma de las gráficas\">\n      <rect width=\"640\" height=\"230\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"20\" y=\"20\" width=\"290\" height=\"190\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"165\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">MRU</text>\n          <text x=\"165\" y=\"100\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">a = 0 · v constante</text>\n          <text x=\"165\" y=\"138\" text-anchor=\"middle\" font-size=\"17\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">x = x₀ + v·t</text>\n          <text x=\"165\" y=\"182\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">x-t: recta · v-t: horizontal</text><rect x=\"330\" y=\"20\" width=\"290\" height=\"190\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"475\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">MRUA</text>\n          <text x=\"475\" y=\"100\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">a constante</text>\n          <text x=\"475\" y=\"138\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">v = v₀ + a·t  ·  x = x₀ + v₀·t + ½·a·t²</text>\n          <text x=\"475\" y=\"182\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">x-t: parábola · v-t: recta</text>\n    </svg>"
