   "svg": "<svg viewBox=\"0 0 640 220\" role=\"img\" aria-label=\"Fórmulas del trabajo, energía cinética, energía potencial y potencia\">\n      <rect width=\"640\" height=\"220\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"16\" y=\"24\" width=\"146\" height=\"172\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"89\" y=\"62\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">Trabajo</text>\n          <text x=\"89\" y=\"116\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">W = F·d·cos α</text>\n          <text x=\"89\" y=\"164\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">julios (J)</text><rect x=\"170\" y=\"24\" width=\"146\" height=\"172\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"243\" y=\"62\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">Cinética</text>\n          <text x=\"243\" y=\"116\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">Ec = ½·m·v²</text>\n          <text x=\"243\" y=\"164\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">por moverse</text><rect x=\"324\" y=\"24\" width=\"146\" height=\"172\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"397\" y=\"62\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">Potencial</text>\n          <text x=\"397\" y=\"116\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">Ep = m·g·h</text>\n          <text x=\"397\" y=\"164\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">por la altura</text><rect x=\"478\" y=\"24\" width=\"146\" height=\"172\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--sun)\" stroke-width=\"3\"/>\n          <text x=\"551\" y=\"62\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--sun)\" font-family=\"Baloo 2, sans-serif\">Potencia</text>\n          <text x=\"551\" y=\"116\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">P = W / t</text>\n          <text x=\"551\" y=\"164\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">vatios (W)</text>\n    </svg>"
