   "svg": "<svg viewBox=\"0 0 640 230\" role=\"img\" aria-label=\"Tabla comparativa del enlace iónico, covalente y metálico con ejemplo y propiedades\">\n      <rect width=\"640\" height=\"230\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"20\" y=\"20\" width=\"190\" height=\"190\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"115\" y=\"54\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">IÓNICO</text>\n          <text x=\"115\" y=\"84\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">metal + no metal</text>\n          <text x=\"115\" y=\"106\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">ceden y captan e⁻</text>\n          <text x=\"115\" y=\"138\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">sólidos duros, frágiles</text>\n          <text x=\"115\" y=\"156\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">conducen disueltos</text>\n          <text x=\"115\" y=\"192\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">NaCl</text><rect x=\"226\" y=\"20\" width=\"190\" height=\"190\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"321\" y=\"54\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">COVALENTE</text>\n          <text x=\"321\" y=\"84\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">no metal + no metal</text>\n          <text x=\"321\" y=\"106\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">comparten e⁻</text>\n          <text x=\"321\" y=\"138\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">moléculas: puntos de</text>\n          <text x=\"321\" y=\"156\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">fusión bajos, no conducen</text>\n          <text x=\"321\" y=\"192\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">H₂O, CO₂</text><rect x=\"432\" y=\"20\" width=\"190\" height=\"190\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"527\" y=\"54\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">METÁLICO</text>\n          <text x=\"527\" y=\"84\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">metal + metal</text>\n          <text x=\"527\" y=\"106\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">mar de electrones</text>\n          <text x=\"527\" y=\"138\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">brillantes, dúctiles</text>\n          <text x=\"527\" y=\"156\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">conducen siempre</text>\n          <text x=\"527\" y=\"192\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">Cu, Fe</text>\n    </svg>"
