   "svg": "<svg viewBox=\"0 0 640 220\" role=\"img\" aria-label=\"Hidrostática, Pascal y Arquímedes con su fórmula y una aplicación\">\n      <rect width=\"640\" height=\"220\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"20\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"115\" y=\"56\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">Hidrostática</text>\n          <text x=\"115\" y=\"100\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">p = d · g · h</text>\n          <text x=\"115\" y=\"138\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más hondo, más presión</text>\n          <text x=\"115\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">presas y submarinos</text><rect x=\"226\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"321\" y=\"56\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">Pascal</text>\n          <text x=\"321\" y=\"100\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">F₁/S₁ = F₂/S₂</text>\n          <text x=\"321\" y=\"138\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">la presión se transmite</text>\n          <text x=\"321\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">frenos y gatos hidráulicos</text><rect x=\"432\" y=\"20\" width=\"190\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"527\" y=\"56\" text-anchor=\"middle\" font-size=\"19\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">Arquímedes</text>\n          <text x=\"527\" y=\"100\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">E = d · g · V</text>\n          <text x=\"527\" y=\"138\" text-anchor=\"middle\" font-size=\"14\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">empuje = peso desalojado</text>\n          <text x=\"527\" y=\"176\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">barcos y globos</text>\n    </svg>"
