   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Caja con dos fuerzas a la derecha de 30 y 20 newtons y una a la izquierda de 10 newtons; resultante 40 newtons a la derecha\">\n        <defs><marker id=\"nf1\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--pen)\"/></marker><marker id=\"nf2\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--red)\"/></marker><marker id=\"nf3\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--leaf)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <rect x=\"100\" y=\"50\" width=\"60\" height=\"50\" rx=\"6\" fill=\"var(--sun)\" stroke=\"var(--ink)\" stroke-width=\"2\"/>\n        <path d=\"M160 64 H 226\" stroke=\"var(--pen)\" stroke-width=\"4\" marker-end=\"url(#nf1)\"/><text x=\"196\" y=\"56\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">30 N</text>\n        <path d=\"M160 88 H 204\" stroke=\"var(--pen)\" stroke-width=\"4\" marker-end=\"url(#nf1)\"/><text x=\"186\" y=\"108\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">20 N</text>\n        <path d=\"M100 75 H 70\" stroke=\"var(--red)\" stroke-width=\"4\" marker-end=\"url(#nf2)\"/><text x=\"72\" y=\"66\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">10 N</text>\n        <path d=\"M60 145 H 196\" stroke=\"var(--leaf)\" stroke-width=\"5\" marker-end=\"url(#nf3)\"/>\n        <text x=\"130\" y=\"170\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">resultante: 30 + 20 − 10 = 40 N →</text>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Disco de hockey deslizando sobre hielo a velocidad constante sin fuerzas\">\n        <defs><marker id=\"nf4\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--pen)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <rect x=\"10\" y=\"118\" width=\"240\" height=\"14\" rx=\"4\" fill=\"var(--water)\" opacity=\".3\"/>\n        <ellipse cx=\"40\" cy=\"110\" rx=\"18\" ry=\"7\" fill=\"var(--ink)\" opacity=\"0.35\"/><ellipse cx=\"110\" cy=\"110\" rx=\"18\" ry=\"7\" fill=\"var(--ink)\" opacity=\"0.6499999999999999\"/><ellipse cx=\"180\" cy=\"110\" rx=\"18\" ry=\"7\" fill=\"var(--ink)\" opacity=\"0.95\"/>\n        <path d=\"M200 92 H 240\" stroke=\"var(--pen)\" stroke-width=\"3\" marker-end=\"url(#nf4)\"/>\n        <text x=\"130\" y=\"66\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">sin rozamiento: misma velocidad</text>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-size=\"12\" fill=\"var(--muted)\" text-anchor=\"middle\"><text x=\"40\" y=\"152\">t = 0 s</text><text x=\"110\" y=\"152\">t = 1 s</text><text x=\"180\" y=\"152\">t = 2 s</text></g>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"La misma fuerza aplicada a un carro vacío y a uno lleno: el vacío acelera más\">\n        <defs><marker id=\"nf5\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--red)\"/></marker><marker id=\"nf6\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--leaf)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <rect x=\"70\" y=\"30\" width=\"60\" height=\"34\" rx=\"4\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"2\"/>\n        <circle cx=\"82\" cy=\"70\" r=\"6\" fill=\"var(--ink)\"/><circle cx=\"118\" cy=\"70\" r=\"6\" fill=\"var(--ink)\"/>\n        <path d=\"M30 47 H 66\" stroke=\"var(--red)\" stroke-width=\"4\" marker-end=\"url(#nf5)\"/>\n        <path d=\"M140 47 H 236\" stroke=\"var(--leaf)\" stroke-width=\"4\" marker-end=\"url(#nf6)\"/><text x=\"190\" y=\"38\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">a grande</text>\n        <rect x=\"70\" y=\"106\" width=\"60\" height=\"34\" rx=\"4\" fill=\"var(--inf)\" stroke=\"var(--ink)\" stroke-width=\"2\"/>\n        <circle cx=\"82\" cy=\"146\" r=\"6\" fill=\"var(--ink)\"/><circle cx=\"118\" cy=\"146\" r=\"6\" fill=\"var(--ink)\"/>\n        <path d=\"M30 123 H 66\" stroke=\"var(--red)\" stroke-width=\"4\" marker-end=\"url(#nf5)\"/>\n        <path d=\"M140 123 H 176\" stroke=\"var(--leaf)\" stroke-width=\"4\" marker-end=\"url(#nf6)\"/><text x=\"200\" y=\"114\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">a pequeña</text>\n        <text x=\"130\" y=\"172\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">misma F, más masa → menos aceleración</text>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Cohete: los gases salen hacia abajo y el cohete sube\">\n        <defs><marker id=\"nf7\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--pen)\"/></marker><marker id=\"nf8\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"var(--red)\"/></marker></defs>\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M130 20 C 146 36, 150 60, 150 100 H 110 C 110 60, 114 36, 130 20 Z\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"2\"/>\n        <circle cx=\"130\" cy=\"62\" r=\"9\" fill=\"var(--water)\"/>\n        <path d=\"M112 100 L 118 140 L 130 118 L 142 140 L 148 100 Z\" fill=\"var(--sun)\" opacity=\".9\"/>\n        <path d=\"M190 100 V 30\" stroke=\"var(--pen)\" stroke-width=\"4\" marker-end=\"url(#nf7)\"/><text x=\"200\" y=\"70\" font-size=\"12\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">sobre el</text><text x=\"200\" y=\"84\" font-size=\"12\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">cohete</text>\n        <path d=\"M70 100 V 166\" stroke=\"var(--red)\" stroke-width=\"4\" marker-end=\"url(#nf8)\"/><text x=\"18\" y=\"130\" font-size=\"12\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">sobre los</text><text x=\"18\" y=\"144\" font-size=\"12\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">gases</text>\n      </svg>",
   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Misma masa de 50 kilos: 490 newtons en la Tierra y 81 newtons en la Luna\">\n        <rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <circle cx=\"70\" cy=\"150\" r=\"60\" fill=\"var(--water)\" opacity=\".5\"/><circle cx=\"190\" cy=\"160\" r=\"40\" fill=\"var(--muted)\" opacity=\".35\"/>\n        <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-weight=\"700\" text-anchor=\"middle\">\n          <text x=\"70\" y=\"40\" font-size=\"14\" fill=\"var(--ink)\">Tierra</text><text x=\"70\" y=\"62\" font-size=\"20\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">490 N</text>\n          <text x=\"190\" y=\"40\" font-size=\"14\" fill=\"var(--ink)\">Luna</text><text x=\"190\" y=\"62\" font-size=\"20\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">81 N</text>\n          <text x=\"130\" y=\"90\" font-size=\"13\" fill=\"var(--muted)\">masa: 50 kg en los dos</text>\n        </g>\n      </svg>"
