   "svg": "<svg viewBox=\"0 0 640 220\" role=\"img\" aria-label=\"Cuatro factores que aumentan la velocidad de reacción con un ejemplo cotidiano\">\n      <rect width=\"640\" height=\"220\" rx=\"16\" fill=\"var(--paper)\"/>\n      <rect x=\"16\" y=\"20\" width=\"146\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"3\"/>\n          <text x=\"89\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Baloo 2, sans-serif\">Temperatura</text>\n          <text x=\"89\" y=\"96\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más calor →</text>\n          <text x=\"89\" y=\"114\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más choques</text>\n          <text x=\"89\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">cocinar en olla exprés</text><rect x=\"170\" y=\"20\" width=\"146\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"3\"/>\n          <text x=\"243\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Baloo 2, sans-serif\">Concentración</text>\n          <text x=\"243\" y=\"96\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más partículas →</text>\n          <text x=\"243\" y=\"114\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más choques</text>\n          <text x=\"243\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">lejía más concentrada</text><rect x=\"324\" y=\"20\" width=\"146\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--sun)\" stroke-width=\"3\"/>\n          <text x=\"397\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"var(--sun)\" font-family=\"Baloo 2, sans-serif\">Superficie</text>\n          <text x=\"397\" y=\"96\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">trocear →</text>\n          <text x=\"397\" y=\"114\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">más contacto</text>\n          <text x=\"397\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">astillas arden antes</text><rect x=\"478\" y=\"20\" width=\"146\" height=\"180\" rx=\"14\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"3\"/>\n          <text x=\"551\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"var(--leaf)\" font-family=\"Baloo 2, sans-serif\">Catalizador</text>\n          <text x=\"551\" y=\"96\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">baja la energía</text>\n          <text x=\"551\" y=\"114\" text-anchor=\"middle\" font-size=\"13\" fill=\"var(--ink)\" font-family=\"Atkinson Hyperlegible, sans-serif\">de activación</text>\n          <text x=\"551\" y=\"168\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">enzimas, tubo de escape</text>\n    </svg>"
